#include "v34_framing.h"
#include <assert.h>
#include <stdio.h>
int main(void){v34_frame_geometry g;assert(v34_frame_geometry_init(&g,V34_SYMBOL_3000,19200));assert(g.data_frames_per_superframe==7&&g.mapping_frames_per_data_frame==15);assert(g.bits_per_data_frame==768&&g.high_frame_bits==52&&g.high_frame_count==3);assert(g.switching_pattern==0x0421);assert(v34_mapping_frame_high(&g,4)&&v34_mapping_frame_high(&g,9)&&v34_mapping_frame_high(&g,14));assert(v34_frame_geometry_init(&g,V34_SYMBOL_3429,33600));assert(g.data_frames_per_superframe==8&&g.mapping_frames_per_data_frame==15);assert(g.bits_per_data_frame==1176&&g.high_frame_bits==79&&g.high_frame_count==6);assert(g.switching_pattern==0x14a5);assert(v34_frame_geometry_init(&g,V34_SYMBOL_3200,31200));assert(g.bits_per_data_frame==V34_MAX_DATA_FRAME_BITS&&g.high_frame_bits==78);assert(v34_frame_geometry_init(&g,V34_SYMBOL_2400,2400));assert(g.high_frame_bits==8&&g.switching_pattern==0x0fff);assert(!v34_frame_geometry_init(&g,V34_SYMBOL_2400,24000));assert(!v34_frame_geometry_init(&g,V34_SYMBOL_3429,31201));puts("v34 data-frame geometry and SWP tests: ok");return 0;}
